  let applied = 0;
  let unmoved = 0;
  let withoutExtent = 0;
  for (const pane of panes) {
    if (pane === source || pane.failed) continue;
    if (!pane.record.extent) {
      withoutExtent += 1;
      continue;
    }
    const target = pane.viewer.getView();
    if (!target) continue;
    const view = extentToView(geo, target.bounds, pane.record.extent);
    if (view && pane.viewer.setView(view)) applied += 1;
    else unmoved += 1;
  }
  // "Nothing happened" has three different reasons and the hint names the real
  // one: the source cut-out can cover the whole other sheet (the documented
  // scales are too different for a fraction-based mapping), the other sheet can
  // document no extent at all, or a combination of both.
  if (applied > 0 && unmoved === 0) {
    updateSyncHint(`Ausschnitt von Karte ${sourceIndex + 1} auf ${applied} weitere Karte${applied === 1 ? '' : 'n'} übertragen.`, 'transferred');
  } else if (applied > 0) {
    updateSyncHint(
      `Ausschnitt von Karte ${sourceIndex + 1} auf ${applied} weitere Karte${applied === 1 ? '' : 'n'} übertragen; ${unmoved} deckt einen zu verschiedenen Maßstab ab und bleibt stehen.`,
      'partial',
    );
  } else if (unmoved > 0) {
    updateSyncHint(
      `Der Ausschnitt von Karte ${sourceIndex + 1} umfasst die andere Karte ganz – die belegten Maßstäbe sind zu verschieden, es wird nichts übertragen.`,
      'scale',
    );
  } else if (withoutExtent > 0 && panes.length > 1) {
    updateSyncHint(`Karte ${sourceIndex + 1} hat keine belegte Ausdehnung – die übrigen Karten bleiben stehen.`, 'no-extent');
  }
}

